func:
let data;
try { data = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload; } catch (err) { data = {}; }
const homedir = os.homedir();
const base = path.resolve(path.join(homedir, 'Downloads'));
const allowed = ['Installers','Documents','Archives','Media','Others'];
const category = allowed.includes(data.category) ? data.category : null;
const filename = path.basename(String(data.filename || ''));
const source = path.resolve(path.join(base, filename));
const target = category ? path.resolve(path.join(base, category, filename)) : null;
let status = 'REJECTED';
let error = null;

if (!category) error = '分類不在白名單';
else if (!filename || filename === '.' || filename === '..') error = '缺少檔名';
else if (!source.startsWith(base + path.sep) || !target.startsWith(base + path.sep)) error = '路徑越界';
else if (!fs.existsSync(source) || !fs.statSync(source).isFile()) { status = 'SKIPPED'; error = '來源檔案不存在'; }
else {
    try { fs.mkdirSync(path.dirname(target), { recursive: true }); if (source !== target) fs.renameSync(source, target); status = 'SUCCESS'; }
    catch (err) { status = 'FAILED'; error = err.message; }
}

const auditDir = path.join(homedir, 'SystemLogs');
fs.mkdirSync(auditDir, { recursive: true });
const audit = { task_id: data.task_id || null, timestamp: new Date().toISOString(), action: 'MOVE_FILE', status, source, target, category, error };
fs.appendFileSync(path.join(auditDir, 'audit_trail.log'), JSON.stringify(audit) + '\n', 'utf-8');
msg.auditStatus = status;
msg.audit = audit;
const title = status === 'SUCCESS' ? '📂 [E2E 管家] 歸檔完成' : '🛡️ [E2E 管家] 動作未執行';
const message = `${status}: ${error || filename}`.replace(/[\r\n]+/g, ' ');
msg.payload = `powershell -NoProfile -Command "[Windows.UI.Notifications.ToastNotificationManager, Windows.UI.Notifications, ContentType = WindowsRuntime] > $null; $template = [Windows.UI.Notifications.ToastNotificationManager]::GetTemplateContent([Windows.UI.Notifications.ToastTemplateType]::ToastText02); $textNodes = $template.GetElementsByTagName('text'); $textNodes.Item(0).AppendChild($template.CreateTextNode('${title}')) > $null; $textNodes.Item(1).AppendChild($template.CreateTextNode('${message}')) > $null; [Windows.UI.Notifications.ToastNotificationManager]::CreateToastNotifier('Windows AI 管家').Show([Windows.UI.Notifications.ToastNotification]::new($template));"`;
return msg;
